using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<Person> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata: {personInfo.Type.Name}");

// Round-trip using the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-trip: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use empty options (no resolver) so resolution fails gracefully.
var emptyOptions = new JsonSerializerOptions();

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata for Person is NOT available (no resolver configured).");
}

// Confirm it works when a resolver IS present
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"With resolver present, TryGetTypeInfo succeeded: {info2!.Type.Name}");
}

record Person(string Name, int Age);

